package review

import (
	"errors"
	"fmt"
	"net/http"

	"github.com/partio-io/cli/internal/github"
)

// ReviewedLabel marks an issue the sweep has acted on, open or closed,
// so the sweep never selects it again.
const ReviewedLabel = "minion-reviewed"

// buildLabels describe approvals and runs of the text before the
// review. A keep removes them: the reviewed text starts clean.
var buildLabels = []string{"minion-approved", "minion-failed", "minion-executing", "do-not-build"}

// olderBuildBranch is the head branch an older build of issue pushed.
func olderBuildBranch(issue int) string {
	return fmt.Sprintf("minion/implement-implement-%d", issue)
}

// refusal is the cause of a valid verdict the gate cannot act on. Run
// records it as no verdict; every other error from actable is a failure
// to talk to GitHub.
type refusal string

func (r refusal) Error() string { return string(r) }

// actable checks, outside dry-run, that the gate can act on v for
// issue: not a rewrite, an open issue and not a pull request, and for a
// duplicate close an open kept issue, which it returns.
func actable(gh github.Client, repo string, issue github.Issue, v Verdict) (*github.Issue, error) {
	switch {
	case v.Outcome == OutcomeRewrite:
		return nil, refusal(fmt.Sprintf("a %s verdict is not acted on yet", OutcomeRewrite))
	case issue.PullRequest != nil:
		return nil, refusal(fmt.Sprintf("#%d is a pull request: the gate never changes one", issue.Number))
	case issue.State != "open":
		return nil, refusal(fmt.Sprintf("#%d is %s: the gate acts on open issues only", issue.Number, issue.State))
	case v.Outcome != OutcomeClose || v.CloseReason != ReasonDuplicate:
		return nil, nil
	}
	kept, err := gh.GetIssue(repo, v.DuplicateOf)
	var status *github.StatusError
	if errors.As(err, &status) && status.Code == http.StatusNotFound {
		return nil, refusal(fmt.Sprintf("kept issue #%d does not exist", v.DuplicateOf))
	}
	if err != nil {
		return nil, fmt.Errorf("read kept issue #%d: %w", v.DuplicateOf, err)
	}
	if kept.PullRequest != nil || kept.State != "open" {
		return nil, refusal(fmt.Sprintf("kept issue #%d is not an open issue, so it does not stay", v.DuplicateOf))
	}
	return &kept, nil
}

// act applies a keep or close verdict to the reviewed issue: one
// evidence comment, the label changes and, for a close, the close with
// its state reason. kept is the issue that stays for a duplicate close.
// It never changes a pull request; it only names an open one from an
// older build in the comment. The evidence comment is found by its
// marker and updated in place, so a run that failed after the comment
// does not post a second one when it runs again.
func act(gh github.Client, repo string, issue github.Issue, v Verdict, kept *github.Issue) error {
	pulls, err := gh.OpenPullsByHead(repo, olderBuildBranch(issue.Number))
	if err != nil {
		return fmt.Errorf("find older build of #%d: %w", issue.Number, err)
	}
	if err := gh.EnsureLabel(repo, ReviewedLabel, "0e8a16", "The proposal review has acted on this issue"); err != nil {
		return err
	}
	if err := gh.UpsertComment(repo, issue.Number, ReviewMarker, evidenceComment(v, kept, pulls)); err != nil {
		return fmt.Errorf("comment on #%d: %w", issue.Number, err)
	}
	if v.Outcome == OutcomeKeep {
		for _, l := range buildLabels {
			if !issue.HasLabel(l) {
				continue
			}
			if err := gh.RemoveLabel(repo, issue.Number, l); err != nil {
				return fmt.Errorf("label #%d: %w", issue.Number, err)
			}
		}
	}
	if err := gh.AddLabels(repo, issue.Number, ReviewedLabel); err != nil {
		return fmt.Errorf("label #%d: %w", issue.Number, err)
	}
	if v.Outcome != OutcomeClose {
		return nil
	}
	reason := github.StateReasonNotPlanned
	if v.CloseReason == ReasonBuilt {
		reason = github.StateReasonCompleted
	}
	if err := gh.CloseIssue(repo, issue.Number, reason); err != nil {
		return fmt.Errorf("close #%d: %w", issue.Number, err)
	}
	return nil
}
package review

import (
	"fmt"
	"strings"

	"github.com/partio-io/cli/internal/github"
)

// row is one tracking line for a valid verdict: number, title, verdict,
// reason and link. A rewrite carries its full proposed text in a
// collapsed section, indented so it stays under its row, with the body
// fenced so its own markup cannot close the section or hide later rows.
func row(issue github.Issue, v Verdict, dryRun bool) string {
	verdict := "**" + v.Outcome + "**"
	if dryRun {
		verdict += " (dry run)"
	}
	line := fmt.Sprintf("- #%d · %s · %s · %s · [link](%s)\n",
		issue.Number, oneLine(issue.Title), verdict, reason(v), issue.HTMLURL)
	if v.Outcome != OutcomeRewrite {
		return line
	}
	return line + indent(rewriteDetails(*v.Rewrite))
}

// noVerdictRow is the tracking line for a missing or invalid verdict.
func noVerdictRow(issue github.Issue, cause string) string {
	return fmt.Sprintf("- #%d · %s · **no verdict** · %s · [link](%s)\n",
		issue.Number, oneLine(issue.Title), oneLine(cause), issue.HTMLURL)
}

func reason(v Verdict) string {
	switch {
	case v.Outcome == OutcomeClose && v.CloseReason == ReasonDuplicate:
		return fmt.Sprintf("duplicate of #%d", v.DuplicateOf)
	case v.Outcome == OutcomeClose:
		return v.CloseReason
	case v.Outcome == OutcomeRewrite && len(v.Rewrite.Changes) > 0:
		return oneLine(strings.Join(v.Rewrite.Changes, "; "))
	}
	return oneLine(v.Fit.Reason)
}

func rewriteDetails(rw Rewrite) string {
	var b strings.Builder
	b.WriteString("\n<details><summary>Proposed rewrite</summary>\n\n")
	fmt.Fprintf(&b, "**Title:** %s\n\n", oneLine(rw.Title))
	fence := fenceFor(rw.Body)
	b.WriteString(fence + "markdown\n")
	b.WriteString(strings.TrimRight(rw.Body, "\n"))
	b.WriteString("\n" + fence + "\n\n</details>\n\n")
	return b.String()
}

// fenceFor returns a backtick fence longer than any backtick run in
// text, so text cannot close it.
func fenceFor(text string) string {
	longest, run := 0, 0
	for _, r := range text {
		if r == '`' {
			run++
			longest = max(longest, run)
		} else {
			run = 0
		}
	}
	return strings.Repeat("`", max(3, longest+1))
}

// indent nests text under a list item, so lines that start with "- "
// in a rewrite body never read as rows of their own.
func indent(text string) string {
	lines := strings.Split(text, "\n")
	for i, l := range lines {
		if l != "" {
			lines[i] = "  " + l
		}
	}
	return strings.Join(lines, "\n")
}

func oneLine(s string) string {
	return strings.Join(strings.Fields(s), " ")
}
package review

import (
	"fmt"
	"strings"

	"github.com/partio-io/cli/internal/github"
)

// ReviewMarker opens every evidence comment the gate posts.
const ReviewMarker = "<!-- partio:review:v1 -->"

// evidenceComment is the comment the gate posts on the reviewed issue:
// the outcome and its reason, every claim with its evidence, verdict
// and excerpt, the fit, built and duplicate decisions, and any open
// pull request from an older build. kept is the issue that stays for a
// duplicate close, and nil otherwise.
// When the excerpts push the comment past GitHub's size limit, the
// comment leaves them out and says so.
func evidenceComment(v Verdict, kept *github.Issue, pulls []github.PullRequest) string {
	if body := renderEvidence(v, kept, pulls, true); len(body) <= maxCommentBody {
		return body
	}
	return renderEvidence(v, kept, pulls, false)
}

func renderEvidence(v Verdict, kept *github.Issue, pulls []github.PullRequest, excerpts bool) string {
	var b strings.Builder
	b.WriteString(ReviewMarker + "\n")
	fmt.Fprintf(&b, "## Proposal review: %s\n\n", v.Outcome)
	fmt.Fprintf(&b, "**Outcome:** %s · **Reason:** %s\n\n", v.Outcome, reason(v))
	if kept != nil {
		fmt.Fprintf(&b, "Duplicate of #%d, which stays: [%s](%s)\n\n", kept.Number, oneLine(kept.Title), kept.HTMLURL)
	}

	fmt.Fprintf(&b, "### Premise: %s\n\n", v.Premise.Verdict)
	if len(v.Premise.Claims) == 0 {
		b.WriteString("No checkable claims.\n\n")
	}
	if !excerpts {
		b.WriteString("Excerpts left out: with them the comment passes GitHub's size limit.\n\n")
	}
	for _, c := range v.Premise.Claims {
		fmt.Fprintf(&b, "- **%s** · %s\n", c.Verdict, oneLine(c.Claim))
		fmt.Fprintf(&b, "  - Evidence: %s\n", oneLine(c.Evidence))
		if excerpts && c.Excerpt != "" {
			fence := fenceFor(c.Excerpt)
			b.WriteString("  - Excerpt:\n\n")
			b.WriteString(indent(indent(fence + "\n" + strings.TrimRight(c.Excerpt, "\n") + "\n" + fence)))
			b.WriteString("\n")
		}
	}
	b.WriteString("\n### Decisions\n\n")
	fmt.Fprintf(&b, "- **Fit:** %s · %s\n", yesNo(v.Fit.Applies, "applies", "does not apply"), oneLine(v.Fit.Reason))
	fmt.Fprintf(&b, "- **Built:** %s", yesNo(v.Built.Built, "yes", "no"))
	if v.Built.Evidence != "" {
		fmt.Fprintf(&b, " · %s", oneLine(v.Built.Evidence))
	}
	b.WriteString("\n- **Duplicates:**")
	if len(v.Duplicates) == 0 {
		b.WriteString(" none found\n")
	} else {
		b.WriteString("\n")
		for _, d := range v.Duplicates {
			fmt.Fprintf(&b, "  - #%d · %s · %s\n", d.Issue, yesNo(d.Same, "same idea", "different idea"), oneLine(d.Why))
		}
	}
	if len(pulls) > 0 {
		b.WriteString("\n### Open pull request from an older build\n\n")
		for _, p := range pulls {
			fmt.Fprintf(&b, "- #%d · [%s](%s) · the review does not change it\n", p.Number, oneLine(p.Title), p.HTMLURL)
		}
	}
	return b.String()
}

func yesNo(ok bool, yes, no string) string {
	if ok {
		return yes
	}
	return no
}
// Package review is the deterministic half of the proposal review. The
// review program writes one verdict file per issue; this package loads
// it, checks it and fails closed, and records it in the tracking issue.
package review

// Outcomes a verdict can carry.
const (
	OutcomeKeep    = "keep"
	OutcomeRewrite = "rewrite"
	OutcomeClose   = "close"
)

// Reasons a close can carry.
const (
	ReasonBuilt          = "built"
	ReasonFalsePremise   = "false-premise"
	ReasonDoesNotApply   = "does-not-apply"
	ReasonDuplicate      = "duplicate"
	ReasonCouldNotVerify = "could-not-verify"
)

// Premise and claim verdicts. NoClaims is valid for the premise only.
const (
	Holds      = "holds"
	Fails      = "fails"
	Unresolved = "unresolved"
	NoClaims   = "no-claims"
)

// Verdict is the contract between the review program and the gate: one
// file per reviewed issue.
type Verdict struct {
	Issue       int         `json:"issue"`
	Outcome     string      `json:"outcome"`
	CloseReason string      `json:"close_reason,omitempty"`
	DuplicateOf int         `json:"duplicate_of,omitempty"`
	Premise     Premise     `json:"premise"`
	Fit         Fit         `json:"fit"`
	Built       Built       `json:"built"`
	Duplicates  []Candidate `json:"duplicates"`
	Rewrite     *Rewrite    `json:"rewrite,omitempty"`
}

// Premise is the check of the issue's factual claims.
type Premise struct {
	Verdict string  `json:"verdict"`
	Claims  []Claim `json:"claims"`
}

// Claim is one factual claim, checked against the repository.
type Claim struct {
	Claim    string `json:"claim"`
	Evidence string `json:"evidence"`
	Verdict  string `json:"verdict"`
	Excerpt  string `json:"excerpt"`
}

// Fit says whether the issue applies to this project.
type Fit struct {
	Applies bool   `json:"applies"`
	Reason  string `json:"reason"`
}

// Built says whether the issue is already built.
type Built struct {
	Built    bool   `json:"built"`
	Evidence string `json:"evidence"`
}

// Candidate is one possible duplicate the review considered.
type Candidate struct {
	Issue int    `json:"issue"`
	Same  bool   `json:"same"`
	Why   string `json:"why"`
}

// Rewrite is the proposed new title and body of the issue.
type Rewrite struct {
	Title   string   `json:"title"`
	Body    string   `json:"body"`
	Changes []string `json:"changes"`
}

