			return Block{}, fmt.Errorf("%w: %s", ErrNoEvidence, m[1])
		}

		b.Claims = append(b.Claims, Claim{
			Statement: m[1],
			Evidence:  strings.TrimSpace(m[2]),
		})
	}

	if len(b.Claims) == 0 {
		return Block{}, ErrNoClaims
	}
	return b, nil
}
