	gh := newFakeGitHub()
	tracking := gh.trackingIssue(77)
	full := NightMarker("2026-10-06") + "\n" + strings.Repeat("x", maxCommentBody-100)
	gh.comments[tracking] = []map[string]any{{"id": int64(400), "body": full}}

