	cont := comments[1]["body"].(string)
	if !strings.HasPrefix(cont, NightMarker("2026-10-06")+"\n### Review night 2026-10-06 (continued)") || !strings.Contains(cont, "- #12 ") {
		t.Errorf("continuation comment is wrong:\n%s", cont)
