package github

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
)

// EditIssue replaces the title and the body of issue number in repo.
// GitHub keeps the old text in the issue's edit history.
func (c Client) EditIssue(repo string, number int, title, body string) error {
	payload, err := json.Marshal(map[string]string{"title": title, "body": body})
	if err != nil {
		return fmt.Errorf("encode edit: %w", err)
	}
	req, err := http.NewRequest(http.MethodPatch,
		fmt.Sprintf("%s/repos/%s/issues/%d", c.BaseURL, repo, number), bytes.NewReader(payload))
	if err != nil {
		return fmt.Errorf("edit issue: %w", err)
	}
	if err := c.Do(req, nil); err != nil {
		return fmt.Errorf("edit issue: %w", err)
	}
	return nil
}

